const charge = (over) => ({ merchantId: 'm_1', amountMinor: 1000, currency: 'USD', plan: 'standard', status: 'captured', capturedAt: 5, ...over });
const refund = (over) => ({ merchantId: 'm_1', chargeId: 'a', amountMinor: 400, feeReturnMinor: 23, currency: 'USD', createdAt: 50, ...over });

test('only captured charges of the merchant inside [from, to) are settled', () => {
  const rows = settle({
    merchantId: 'm_1',
    from: 10,
    to: 100,
    refunds: [],
    charges: [
      charge({ id: 'a', capturedAt: 10 }),
      charge({ id: 'b', capturedAt: 99, amountMinor: 2000 }),
      charge({ id: 'c', capturedAt: 100 }),
      charge({ id: 'd', capturedAt: 9 }),
      charge({ id: 'e', status: 'failed', capturedAt: 20 }),
      charge({ id: 'f', status: 'pending', capturedAt: 20 }),
      charge({ id: 'g', status: 'authorized', capturedAt: 20 }),
      charge({ id: 'h', merchantId: 'm_2', capturedAt: 20 }),
    ],
  });
  assert.deepEqual(rows, [
    { currency: 'USD', grossMinor: 3000, refundsMinor: 0, feesMinor: 59 + 88, netMinor: 3000 - 147, payoutMinor: 2853, carryoverMinor: 0 },
  ]);
});

test('no row when nothing counted', () => {
  assert.deepEqual(
    settle({ merchantId: 'm_1', from: 0, to: 100, charges: [charge({ id: 'a', status: 'pending' })], refunds: [refund({ createdAt: 100 })] }),
    [],
  );
});

test('one row per currency, sorted by currency code', () => {
  const rows = settle({
    merchantId: 'm_1',
    from: 0,
    to: 100,
    charges: [
      charge({ id: 'u', currency: 'USD' }),
      charge({ id: 'e', currency: 'EUR', amountMinor: 2000, plan: 'growth' }),
    ],
    refunds: [refund({ currency: 'GBP', amountMinor: 100, feeReturnMinor: 5, merchantId: 'm_1' })],
  });
  assert.deepEqual(rows.map((r) => r.currency), ['EUR', 'GBP', 'USD']);
  assert.deepEqual(rows[0], { currency: 'EUR', grossMinor: 2000, refundsMinor: 0, feesMinor: 75, netMinor: 1925, payoutMinor: 1925, carryoverMinor: 0 });
  assert.deepEqual(rows[1], { currency: 'GBP', grossMinor: 0, refundsMinor: 100, feesMinor: -5, netMinor: -95, payoutMinor: 0, carryoverMinor: 95 });
  assert.deepEqual(rows[2], { currency: 'USD', grossMinor: 1000, refundsMinor: 0, feesMinor: 59, netMinor: 941, payoutMinor: 941, carryoverMinor: 0 });
});

test('refunds in window reduce net and returned fees reduce fees', () => {
  const rows = settle({
    merchantId: 'm_1',
    from: 0,
    to: 100,
    charges: [charge({ id: 'a' })],
    refunds: [refund({}), refund({ createdAt: 100 }), refund({ merchantId: 'm_2' })],
  });
  assert.deepEqual(rows, [
    { currency: 'USD', grossMinor: 1000, refundsMinor: 400, feesMinor: 36, netMinor: 564, payoutMinor: 564, carryoverMinor: 0 },
  ]);
});

test('negative net is not paid out and the shortfall carries over', () => {
  const rows = settle({
    merchantId: 'm_1',
    from: 100,
    to: 200,
    charges: [charge({ id: 'a', capturedAt: 5 }), charge({ id: 'b', capturedAt: 150, amountMinor: 100 })],
    refunds: [refund({ createdAt: 150, amountMinor: 1000, feeReturnMinor: 59 })],
  });
  // gross 100, fee 33 - 59 returned = -26, net = 100 - 1000 + 26 = -874
  assert.deepEqual(rows, [
    { currency: 'USD', grossMinor: 100, refundsMinor: 1000, feesMinor: -26, netMinor: -874, payoutMinor: 0, carryoverMinor: 874 },
  ]);
});

test('zero net keeps carryover 0', () => {
  const [row] = settle({
    merchantId: 'm_1',
    from: 0,
    to: 100,
    charges: [charge({ id: 'a', amountMinor: 59 + 0, plan: 'standard' })],
    refunds: [refund({ amountMinor: 59 - 32, feeReturnMinor: 0 })],
  });
  // fee on 59 = round(1.711) = 2 + 30 = 32; net = 59 - 27 - 32 = 0
  assert.equal(row.netMinor, 0);
  assert.ok(Object.is(row.payoutMinor, 0));
  assert.ok(Object.is(row.carryoverMinor, 0));
});
EOF
